package com.ymahack.challenge;
import android.Manifest; import android.app.*; import android.content.*; import android.content.pm.PackageManager; import android.os.*; import android.webkit.*; import java.util.Calendar;
public class MainActivity extends Activity {
 static final String CHANNEL="daily_challenge_reminders";
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(android.graphics.Color.TRANSPARENT);getWindow().setNavigationBarColor(0xff0b0e15);if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(CHANNEL,"תזכורות אתגר יומי",NotificationManager.IMPORTANCE_DEFAULT);getSystemService(NotificationManager.class).createNotificationChannel(c);} WebView w=new WebView(this);setContentView(w);WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);s.setTextZoom(100);w.setOverScrollMode(2);w.setWebViewClient(new WebViewClient());w.setWebChromeClient(new WebChromeClient());w.addJavascriptInterface(new Bridge(this),"Android");w.loadUrl("file:///android_asset/index.html");if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},1001);}
 public static class Bridge {final Context c;Bridge(Context x){c=x.getApplicationContext();}@JavascriptInterface public void scheduleReminder(int h,int m,boolean enabled){AlarmManager a=(AlarmManager)c.getSystemService(ALARM_SERVICE);Intent i=new Intent(c,ReminderReceiver.class);PendingIntent p=PendingIntent.getBroadcast(c,9017,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);a.cancel(p);if(!enabled)return;Calendar d=Calendar.getInstance();d.set(Calendar.HOUR_OF_DAY,Math.max(0,Math.min(23,h)));d.set(Calendar.MINUTE,Math.max(0,Math.min(59,m)));d.set(Calendar.SECOND,0);if(d.getTimeInMillis()<=System.currentTimeMillis())d.add(Calendar.DATE,1);a.setInexactRepeating(AlarmManager.RTC_WAKEUP,d.getTimeInMillis(),AlarmManager.INTERVAL_DAY,p);}}
 public static class ReminderReceiver extends BroadcastReceiver {public void onReceive(Context c,Intent i){PendingIntent p=PendingIntent.getActivity(c,9018,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CHANNEL):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_popup_reminder).setContentTitle("האתגר שלך מחכה לך").setContentText("גם היום אפשר לעשות צעד אחד קטן קדימה.").setAutoCancel(true).setContentIntent(p);((NotificationManager)c.getSystemService(NOTIFICATION_SERVICE)).notify(9017,b.build());}}
}